def mean_se(x, axis=0):
    """Sample mean and its standard error (sample standard deviation / sqrt(M))."""
    x = np.asarray(x, dtype=float)
    return x.mean(axis=axis), x.std(axis=axis, ddof=1) / np.sqrt(x.shape[axis])


