N_LOC = 32
gs32 = GS[N_LOC][1.0]
v_loc = snapshots(24, gs32["B"], 4000)
obs_true = local_observables(lambda s: log_amplitude(gs32["B"], jnp.asarray(s)), v_loc, 1.0)
